script:
(function runMailScript(current, template, email, email_action, event) {
    var ticketNumber = current.getValue('ticket_number');
    var bkgRef = current.getValue('booking_reference');
    var portalUrl = '/metro?id=my_metro_bookings&sys_id=' + current.getUniqueValue();

    template.print('<div style="margin: 16px 0; padding: 16px; background-color: #F8FAFC; border: 1px solid #CBD5E1; border-radius: 6px; text-align: center;">');
    template.print('<p style="margin: 0; font-size: 12px; color: #64748B; text-transform: uppercase;">Metro Pass Ticket Number</p>');
    template.print('<h2 style="margin: 4px 0 12px 0; color: #0F172A; font-family: monospace;">' + ticketNumber + '</h2>');
    template.print('<p style="font-size: 13px; color: #475569; margin: 8px 0;">Your vector QR pass is attached to this email (<strong>ticket_' + ticketNumber + '.svg</strong>).</p>');
    template.print('<p style="font-size: 13px; color: #475569; margin: 8px 0;">You can also display your active digital pass on your smartphone anytime:</p>');
    template.print('<div style="margin-top: 12px;"><a href="' + portalUrl + '" style="background-color: #0284C7; color: #ffffff; padding: 10px 20px; text-decoration: none; border-radius: 4px; font-weight: bold; display: inline-block;">Open Digital Pass</a></div>');
    template.print('</div>');
})(current, template, email, email_action, event);

(function runMailScript(current, template, email, email_action, event) {
    var travelDate = current.getValue('travel_date');
    var pax = current.getValue('passenger_count') || '1';
    var fare = current.getValue('total_fare') || '0.00';
    var currency = gs.getProperty('x_mtts.default_currency', 'USD');

    template.print('<table style="width: 100%; border-collapse: collapse; margin: 12px 0; font-size: 14px;">');
    template.print('<tr><td style="padding: 6px; border-bottom: 1px solid #E2E8F0; color: #64748B;">Travel Date:</td><td style="padding: 6px; border-bottom: 1px solid #E2E8F0; font-weight: bold;">' + travelDate + '</td></tr>');
    template.print('<tr><td style="padding: 6px; border-bottom: 1px solid #E2E8F0; color: #64748B;">Passengers:</td><td style="padding: 6px; border-bottom: 1px solid #E2E8F0; font-weight: bold;">' + pax + '</td></tr>');
    template.print('<tr><td style="padding: 6px; border-bottom: 1px solid #E2E8F0; color: #64748B;">Total Fare:</td><td style="padding: 6px; border-bottom: 1px solid #E2E8F0; font-weight: bold; color: #0284C7;">' + currency + ' ' + fare + '</td></tr>');
    template.print('</table>');
})(current, template, email, email_action, event);
